-- sql
WITH _hq_raw AS (SELECT "created_at" AS _hq_row_1, "amount_cents" AS _hq_row_2, NULL AS _hq_row_3, "status" AS _hq_row_4, NULL AS _hq_row_5 FROM "analytics"."orders" WHERE "tenant_id" = $1 AND "created_at" < (CASE WHEN pg_typeof((SELECT "created_at" FROM "analytics"."orders" LIMIT 0)) = 'date'::regtype THEN CAST($2 AS timestamp) AT TIME ZONE 'UTC' ELSE CAST($2 AS timestamp) AT TIME ZONE 'UTC' END)),
_hq_source AS (SELECT (CASE WHEN pg_typeof(_hq_row_1) = 'date'::regtype THEN (_hq_row_1)::timestamp AT TIME ZONE 'Europe/Berlin' ELSE (_hq_row_1)::timestamptz END) AS _hq_time, _hq_row_2 AS _hq_v0, _hq_row_3 AS _hq_a0, _hq_row_4 AS _hq_v1, _hq_row_5 AS _hq_a1 FROM _hq_raw WHERE (_hq_row_1 IS NOT NULL)),
_hq_bounds AS (SELECT * FROM (SELECT (CASE WHEN CAST($3 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($3 AS text) AS timestamptz) ELSE CAST(CAST($3 AS text) AS timestamp) AT TIME ZONE 'Europe/Berlin' END) AS _hq_lower) AS _hq_step0 CROSS JOIN LATERAL (SELECT (CASE WHEN CAST($4 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($4 AS text) AS timestamptz) ELSE CAST(CAST($4 AS text) AS timestamp) AT TIME ZONE 'Europe/Berlin' END) AS _hq_upper) AS _hq_step1 CROSS JOIN LATERAL (SELECT ((date_trunc('week', (_hq_lower AT TIME ZONE 'Europe/Berlin') + INTERVAL '1 day') - INTERVAL '1 day') AT TIME ZONE 'Europe/Berlin') AS _hq_first) AS _hq_step2 CROSS JOIN LATERAL (SELECT ((date_trunc('week', (_hq_upper AT TIME ZONE 'Europe/Berlin') + INTERVAL '1 day') - INTERVAL '1 day') AT TIME ZONE 'Europe/Berlin') AS _hq_last) AS _hq_step3),
_hq_series AS (SELECT (((_hq_first AT TIME ZONE 'Europe/Berlin') + (generate_series(0, ((((date_trunc('week', ((_hq_last AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date - (date_trunc('week', ((_hq_first AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date) / 7)::bigint + 1 + 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((date_trunc('week', ((_hq_last AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date - (date_trunc('week', ((_hq_first AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date) / 7)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'Europe/Berlin') + (_hq_calendar_index + 1) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin') <= (((_hq_first AT TIME ZONE 'Europe/Berlin') + (_hq_calendar_index) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer)) - 1)) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin') AS _hq_period FROM _hq_bounds),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time < (((_hq_last AT TIME ZONE 'Europe/Berlin') + (1) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin'))),
_hq_skeleton AS (SELECT * FROM _hq_series),
_hq_fan0 AS (SELECT *, GREATEST(((date_trunc('week', (_hq_time AT TIME ZONE 'Europe/Berlin') + INTERVAL '1 day') - INTERVAL '1 day') AT TIME ZONE 'Europe/Berlin'), _hq_first) AS _hq_period FROM _hq_scanned),
_hq_agg0 AS (SELECT _hq_period, SUM(_hq_v0) AS _hq_m0 FROM _hq_fan0 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period),
_hq_fan1 AS (SELECT *, GREATEST(((date_trunc('week', (_hq_time AT TIME ZONE 'Europe/Berlin') + INTERVAL '1 day') - INTERVAL '1 day') AT TIME ZONE 'Europe/Berlin'), _hq_first) AS _hq_period FROM _hq_scanned),
_hq_agg1 AS (SELECT _hq_period, COUNT(_hq_v1) AS _hq_m1 FROM _hq_fan1 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period),
_hq_values AS (SELECT CAST((s._hq_period AT TIME ZONE 'Europe/Berlin') AS date) AS period, SUM(m0._hq_m0) OVER (ORDER BY s._hq_period ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "running", coalesce(SUM(m1._hq_m1) OVER (ORDER BY s._hq_period ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 0) AS "runningOrders" FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period),
_hq_result AS (SELECT "period", "running", "runningOrders" FROM _hq_values UNION ALL SELECT NULL AS "period", NULL AS "running", NULL AS "runningOrders" FROM _hq_bounds WHERE 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((date_trunc('week', ((_hq_last AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date - (date_trunc('week', ((_hq_first AT TIME ZONE 'Europe/Berlin')) + INTERVAL '1 day') - INTERVAL '1 day')::date) / 7)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'Europe/Berlin') + (_hq_calendar_index + 1) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin') <= (((_hq_first AT TIME ZONE 'Europe/Berlin') + (_hq_calendar_index) * INTERVAL '7 days') AT TIME ZONE 'Europe/Berlin')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer) + 0 = 1) SELECT "period", "running", "runningOrders" FROM _hq_result ORDER BY "period" ASC

